with a as(select * from public.authors where open_library_id=any(array['OL22258A']::text[])),w as(select * from public.works where open_library_id=any(array['OL167173W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9780466619035','9789046113639']::text[]) or open_library_edition_id=any(array['OL22235932M','OL47139255M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987126001 and 987126999),'editions',(select count(*) from public.editions where id between 987226001 and 987226999),'authors',(select count(*) from public.authors where id between 987326001 and 987326999))) as preflight;
